// Reading a storefront catalogue a GM typed, pasted or uploaded.
//
// **One implementation, on this side.** The example is generated by the window, because
// only the window has the sheet templates; the reading happens here, because this is what
// stores the result. A parser mirrored into both languages would be two things to keep in
// step for no gain - the preview a GM sees is a round trip to this function, so what they
// are shown is literally what would be stored.
//
// **Problems are collected, never thrown.** A GM with one bad row wants to know which row,
// not to be handed an exception and an empty screen. Everything below either parses or
// reports a line number, and one unreadable row never costs the other forty.
//
// Three input shapes, sniffed rather than declared:
//
//   JSON      - an object keyed by catalogue, or an array of rows each naming its own.
//               Sniffed carefully: a leading `[` is NOT enough, because `[weapons]` opens
//               a section in the other format. See looksLikeJson.
//   delimited - tabs if the file has them, otherwise commas, or semicolons where Excel's
//               regional settings produced them.
//
// The delimited reader does real RFC-4180 quoting rather than splitting on the separator.
// That is not fastidiousness: item names in this hobby contain commas, and the CharWN
// importer already carries a note about exports containing "Kit, Cyberdoc". An unquoted
// comma silently shifts every column after it, which is the kind of wrong that gets stored
// and believed.

/** A byte-order mark at the front of a file Excel saved. Invisible, and breaks the first header. */
const { parseAmount, formatAmount } = require('../systemBuilder/currencies');
const { valueProblem } = require('../systemBuilder/itemTypes');
const stripBom = (text) => (text.charCodeAt(0) === 0xfeff ? text.slice(1) : text);

/**
 * Which of the two formats this is.
 *
 * A leading `{` is JSON and nothing else is. A leading `[` is **not** enough on its own,
 * because the sectioned format opens with one too - `[weapons]` is a section header, not a
 * JSON array, and sniffing on the bracket alone read every example this app hands out as
 * broken JSON. So a `[` counts only when what follows it could start a JSON value.
 */
const looksLikeJson = (text) => {
  if (text.startsWith('{')) return true;
  if (!text.startsWith('[')) return false;
  const next = text.slice(1).trimStart()[0];
  return next === '{' || next === '"' || next === '[' || next === ']';
};

/** Lines that carry no data: blank, or a comment the example itself is full of. */
const isSkippable = (line) => !line.trim() || line.trim().startsWith('#');

/** `[weapons]` opens a section, as does `[MELEE WEAPONS]`, a type's name (8a7a1). Anything else is data. */
const sectionOf = (line) => {
  const m = /^\s*\[\s*([a-z0-9_][a-z0-9_ '-]*?)\s*\]\s*$/i.exec(line);
  return m ? m[1].toLowerCase() : null;
};

/** A name as sections and headers are matched: any case, spaces and underscores alike. */
const plain = (text) => String(text || '').trim().toLowerCase().replace(/[\s_]+/g, ' ');

/**
 * What a section is (8a7a1; decided 2026-11-20, mockup item-types-in-shops.html): one of the system's own item types, by its
 * id, its name or what one is called (GUNS, GUN, guns), whose rows are lines of that type; or a shelf, as always. A type
 * wins where a shelf has its name too (a type called WEAPONS), so the GM's own types are always reachable; rows already saved
 * under a shelf keep selling. With `options.shelves`, a section that is neither is said rather than saved where nothing sells.
 */
const resolveSection = (name, options) => {
  const type = (options.types || []).find((t) => [t.id, t.label, t.one].some((n) => n && plain(n) === plain(name)));
  if (type) return { key: `type:${type.id}`, type };
  if (options.shelves && !options.shelves.includes(name)) return { unknown: true };
  return { key: name };
};

/** A cell read as its column holds it: a number for a NUMBER or a COUNT, one of the words for PICK ONE, else the text. */
const cellValue = (column, text) => {
  if (column.kind === 'number' || column.kind === 'count') { const n = Number(text.replace(/,/g, '')); return text && Number.isFinite(n) ? n : text; }
  if (column.kind === 'pick') return (column.options || []).find((w) => plain(w) === plain(text)) ?? text;
  return text;
};

/**
 * Which character separates the columns.
 *
 * Tabs win outright when present, because a tab in a pasted table came from a spreadsheet
 * or a PDF and is never punctuation. Otherwise it is whichever of comma and semicolon
 * appears more - Excel writes semicolons wherever the regional list separator is one, and
 * a GM in Germany should not have to know that.
 */
const delimiterOf = (text) => {
  if (text.includes('\t')) return '\t';
  const commas = (text.match(/,/g) || []).length;
  const semis = (text.match(/;/g) || []).length;
  return semis > commas ? ';' : ',';
};

/**
 * One delimited line, honouring quotes.
 *
 * `"Kit, Cyberdoc"` is one cell. `""` inside a quoted cell is a literal quote. Anything
 * outside quotes splits on the delimiter. A line with an unclosed quote is reported by the
 * caller rather than swallowing the rest of the file.
 */
const splitRow = (line, delimiter) => {
  const cells = [];
  let cell = '';
  let quoted = false;
  let closed = true;

  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"') {
        if (line[i + 1] === '"') { cell += '"'; i += 1; } else { quoted = false; closed = true; }
      } else cell += ch;
    } else if (ch === '"' && cell.trim() === '') {
      quoted = true;
      closed = false;
      cell = '';
    } else if (ch === delimiter) {
      cells.push(cell.trim());
      cell = '';
    } else cell += ch;
  }
  cells.push(cell.trim());
  return { cells, closed };
};

/** A price a GM typed: `1,000`, `$500`, `2.5k` is not supported but `2500` is. */
const readPrice = (raw) => {
  const text = String(raw == null ? '' : raw).trim().replace(/[$£€\s,]/g, '');
  if (!text) return null;
  const n = Number(text);
  if (!Number.isFinite(n) || n < 0) return null;
  return n;
};

/**
 * An id for a row, from its name.
 *
 * Generated rather than asked for. A GM transcribing a book table should not also have to
 * invent stable identifiers, and a name is what the sheet stores anyway - which is what
 * ownedItems matches on when the thing is later sold.
 */
const slug = (name) => String(name || '').trim().toLowerCase()
  .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

/** Why a price written in a currency could not be read, for the GM (currencies.js parseAmount). */
const priceProblem = (reason, raw, currency) => {
  const coins = Array.isArray(currency.denominations) ? currency.denominations : [];
  if (reason === 'which_coin') return `price "${raw}" needs a coin, like ${raw} ${coins[0].short || coins[0].name}`;
  if (reason === 'unknown_coin') return `price "${raw}" names a coin ${currency.name} does not have`;
  if (reason === 'too_precise') return `price "${raw}" has more decimals than ${currency.name} has (${currency.decimals || 0})`;
  if (reason === 'negative') return `price "${raw}" is below zero`;
  return `price "${raw || ''}" is not a number`;
};

/**
 * Turn one row of values into a catalogue entry, or say what is wrong with it.
 *
 * In a custom system with currencies, `options.currencyOf(catalogue)` is the catalogue's
 * currency, and the price is read as people write it in that currency ("2gp 5sp", "$4.34",
 * "1.234,56") into whole smallest units, with `read` saying how it was read for the preview
 * (decided with the user, 2026-10-02). Otherwise prices are read as they always have been.
 */
const readRow = (catalogue, columns, cells, line, problems, options = {}) => {
  const values = {};
  columns.forEach((col, i) => { values[col] = (cells[i] ?? '').trim(); });

  const name = (values.name || '').trim();
  if (!name) {
    problems.push({ line, catalogue, message: 'no name, so there is nothing to sell' });
    return null;
  }

  const currency = options.currencyOf ? options.currencyOf(catalogue) : null;
  let price;
  let read;
  if (currency) {
    const got = parseAmount(currency, values.price);
    const reason = !got.ok ? got.reason : got.amount < 0 ? 'negative' : null;
    if (reason) {
      problems.push({ line, catalogue, name, message: priceProblem(reason, values.price, currency) });
      return null;
    }
    price = got.amount;
    read = formatAmount(currency, got.amount);
  } else {
    price = readPrice(values.price);
    if (price === null) {
      problems.push({
        line, catalogue, name,
        message: `price "${values.price || ''}" is not a number`,
      });
      return null;
    }
  }

  // A line of an item type (8a7a1): each of the type's columns by its id or its name, its value read as the column holds
  // it and checked as the builder checks an item's; one that doesn't fit leaves the row out, said. A blank is kept blank
  // and noted, for the GM to fill in or leave. The rest of the columns (a description) ride along as words.
  const type = options.type;
  if (type) {
    const fields = {};
    const blank = [];
    const byHeader = new Map(columns.map((col) => [plain(col), col]));
    for (const column of type.columns) {
      const header = byHeader.get(plain(column.id)) ?? byHeader.get(plain(column.label));
      const text = header ? values[header] : '';
      const label = String(column.label || column.id).toUpperCase();
      if (!text) { blank.push(label); continue; }
      const value = cellValue(column, text);
      const problem = valueProblem(column, value, options.names || { known: () => true, refused: (n) => `@${n}` });
      if (problem) {
        problems.push({ line, catalogue, name, message: `${label} "${text}": ${problem}` });
        return null;
      }
      fields[column.id] = value;
    }
    const known = new Set(type.columns.flatMap((c) => [plain(c.id), plain(c.label)]));
    for (const col of columns) if (col !== 'name' && col !== 'price' && !known.has(plain(col)) && values[col]) fields[col] = values[col];
    if (blank.length) (options.notes || []).push({ line, catalogue, name, message: `${blank.join(', ')} left blank` });
    return { id: slug(name), name, price, fields, type: type.id, line, ...(read ? { read } : {}) };
  }

  // Everything that is not name or price fills the sheet when the item is bought. Blank
  // cells are dropped rather than stored, so an empty column never overwrites anything.
  const fields = {};
  for (const col of columns) {
    if (col === 'name' || col === 'price') continue;
    if (values[col]) fields[col] = values[col];
  }

  return { id: slug(name), name, price, fields, line, ...(read ? { read } : {}) };
};

/** A section that is neither a shelf nor one of the system's types, said with what there is to choose from. */
const unknownSection = (named, options) => {
  const types = (options.types || []).map((t) => String(t.label || t.id).toUpperCase());
  return { line: 0, catalogue: named, message: `no ${types.length ? 'item type or shelf' : 'shelf'} is called ${String(named).toUpperCase()}${types.length ? ` (types: ${types.join(', ')})` : ''}` };
};

/** JSON in, in either of the two shapes somebody would reasonably write. */
const parseJson = (text, problems, options) => {
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    problems.push({ line: 0, message: `not valid JSON: ${err.message}` });
    return {};
  }

  const sections = {};
  const take = (named, rows) => {
    const section = resolveSection(plain(named), options);
    if (section.unknown) { problems.push(unknownSection(named, options)); return; }
    const catalogue = section.key;
    if (!Array.isArray(rows)) {
      problems.push({ line: 0, catalogue, message: 'expected a list of items' });
      return;
    }
    const out = [];
    rows.forEach((row, i) => {
      if (!row || typeof row !== 'object') {
        problems.push({ line: i + 1, catalogue, message: 'not an item' });
        return;
      }
      const columns = Object.keys(row).filter((c) => c !== 'catalogue');
      const cells = columns.map((c) => (row[c] == null ? '' : String(row[c])));
      const entry = readRow(catalogue, columns.map((c) => c.toLowerCase()), cells, i + 1, problems, { ...options, type: section.type });
      if (entry) out.push(entry);
    });
    sections[catalogue] = out;
  };

  if (Array.isArray(data)) {
    // One flat list, each row naming its own catalogue.
    const grouped = {};
    data.forEach((row, i) => {
      const catalogue = row && row.catalogue ? String(row.catalogue) : '';
      if (!catalogue) {
        problems.push({ line: i + 1, message: 'no catalogue on this row' });
        return;
      }
      (grouped[catalogue] ||= []).push(row);
    });
    Object.entries(grouped).forEach(([c, rows]) => take(c, rows));
  } else if (data && typeof data === 'object') {
    Object.entries(data).forEach(([c, rows]) => take(c, rows));
  } else {
    problems.push({ line: 0, message: 'expected an object or a list' });
  }
  return sections;
};

/** The sectioned delimited format the example is written in. */
const parseDelimited = (text, problems, options) => {
  const delimiter = delimiterOf(text);
  const lines = text.split(/\r\n|\r|\n/);
  const sections = {};

  let catalogue = null;
  let columns = null;
  let type = null;
  let skipping = false;

  lines.forEach((raw, i) => {
    const line = i + 1;
    if (isSkippable(raw)) return;

    const opened = sectionOf(raw);
    if (opened) {
      const section = resolveSection(opened, options);
      columns = null;
      skipping = !!section.unknown;
      if (skipping) { problems.push({ ...unknownSection(opened, options), line }); catalogue = null; return; }
      catalogue = section.key;
      type = section.type || null;
      sections[catalogue] ||= [];
      return;
    }
    if (skipping) return;

    const { cells, closed } = splitRow(raw, delimiter);
    if (!closed) {
      problems.push({ line, catalogue, message: 'a quote is opened and never closed' });
      return;
    }

    if (!catalogue) {
      problems.push({ line, message: 'a row before any [section], so nothing knows what it is' });
      return;
    }

    // The first data row of a section names its columns.
    if (!columns) {
      columns = cells.map((c) => c.trim().toLowerCase());
      if (!columns.includes('name')) {
        problems.push({ line, catalogue, message: 'the header has no name column' });
        columns = null;
      } else if (!columns.includes('price')) {
        problems.push({ line, catalogue, message: 'the header has no price column' });
        columns = null;
      }
      return;
    }

    const entry = readRow(catalogue, columns, cells, line, problems, { ...options, type });
    if (entry) sections[catalogue].push(entry);
  });

  return sections;
};

/**
 * Read a catalogue, whatever the GM gave us.
 *
 * Returns `{ sections, problems, notes, format }`. `sections` is catalogue id -> entries, and is
 * whatever could be read - a file with problems still yields the rows that were fine, so a
 * preview can show both at once. A section of an item type (8a7a1) is `type:<id>`, its rows
 * with `type` and their columns in `fields`; `notes` says what was left blank, nothing wrong.
 *
 * `options`: `currencyOf(catalogue)` for a custom system's money; `types`, the system's own item
 * types, and `names`, its names for dice; `shelves`, the shelf ids, so a section that is none of
 * them is said.
 */
const parseCatalogue = (input, options = {}) => {
  const problems = [];
  const notes = [];
  const text = stripBom(String(input == null ? '' : input)).trim();
  if (!text) return { sections: {}, problems: [{ line: 0, message: 'nothing to read' }], notes, format: null };

  const json = looksLikeJson(text);
  const withNotes = { ...options, notes };
  const sections = json ? parseJson(text, problems, withNotes) : parseDelimited(text, problems, withNotes);

  // Two rows of one thing is a GM editing in a hurry, not a catalogue with two prices for
  // a pistol. Later wins, and they are told.
  for (const [catalogue, rows] of Object.entries(sections)) {
    const seen = new Map();
    for (const row of rows) {
      if (seen.has(row.id)) {
        problems.push({
          line: row.line, catalogue, name: row.name,
          message: `a second "${row.name}"; the later one is used`,
        });
      }
      seen.set(row.id, row);
    }
    sections[catalogue] = [...seen.values()];
  }

  return { sections, problems, notes, format: json ? 'json' : 'delimited' };
};

module.exports = {
  parseCatalogue, splitRow, delimiterOf, readPrice, slug, stripBom, looksLikeJson, sectionOf, resolveSection,
};
